code.triRel:
function triRel(lo,up,simple) {
  const l=TRIGRAMS[lo],u=TRIGRAMS[up];
  if(!l||!u) return "";
  if(lo===up) return simple
    ? `${l.name} doubled — fully immersed in ${l.nature.toLowerCase()}. Embrace it, but stay aware.`
    : `When ${l.name} doubles, its quality reaches absolute expression. ${l.nature} above and below — no counterbalance. Embody this completely, but watch for its shadow.`;
  if(simple) return `${u.name} (${u.nature.toLowerCase()}) above, ${l.name} (${l.nature.toLowerCase()}) below. Your outer world reflects ${u.q.split(",")[0].trim().toLowerCase()} energy; your inner world holds ${l.q.split(",")[0].trim().toLowerCase()} energy.`;
  const m={
    "heaven,earth":"Heaven above Earth — energies moving apart. Separation. Yet sometimes things must come apart before they come together truly.",
    "earth,heaven":"Earth above Heaven — the receptive meets the creative. Perfect communion. Energies flowing toward each other.",
    "water,fire":"Water above Fire — the pot on the flame. Opposing forces in dynamic balance. Completion through tension.",
    "fire,water":"Fire above Water — clarity above danger. Energies moving apart. Almost complete, but the last step is hardest.",
    "thunder,wind":"Thunder and Wind — what thunder shakes loose, wind carries everywhere. Shock of recognition, then gradual permeation.",
    "wind,thunder":"Wind above Thunder — gentle influence before decisive action. Understanding arrives softly, then erupts.",
    "mountain,lake":"Mountain and Lake — stillness and joy connected at invisible depths.",
    "lake,mountain":"Lake above Mountain — joy on stillness. When truly grounded, joy is effortless.",
  };
  return m[`${lo},${up}`]||`${u.name} above, ${l.name} below. Outer: ${u.q.split(",")[0].trim().toLowerCase()} energy. Inner: ${l.q.split(",")[0].trim().toLowerCase()} energy. The lesson lives in this interplay.`;
}

code.getThemeForDay:
function getThemeForDay(day) {
  for (const key in LESSON_THEMES) {
    const [s, e] = LESSON_THEMES[key].range;
    if (day >= s && day <= e) return { ...LESSON_THEMES[key], key };
  }
  return { ...LESSON_THEMES["undoing_meaning"], key: "undoing_meaning" };
}

